      "ballot_id": "B043",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "A fundamental prediction and convincing realization of a new topological state of matter, with a profound continuing influence on quantum materials.",
        "attribution": "Kane and Mele provided the defining quantum spin Hall theory; Molenkamp led a decisive experimental realization.",
        "maturity": "The physics is independently established, conceptually coherent, and has matured across many material systems.",
        "uncertainties": [
          "Credit for the wider topological-insulator experimental programme extends beyond a three-person award."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance transformed spin-dependent tunnelling from a phenomenon into a broadly useful technology.",
        "attribution": "Moodera, Miyazaki, and Parkin made central experimental and technological contributions to the effect and its practical magnetic-junction implementation.",
        "maturity": "The effect is robust, reproducible, theoretically understood, and central to deployed spintronic devices.",
        "uncertainties": [
          "The boundary between the original observation and subsequent device engineering requires careful credit definition."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory supplied a quantitatively productive framework for correlated electrons and linked model physics to real materials.",
        "attribution": "These three are among the principal architects of the modern formulation and its connection to electronic-structure theory.",
        "maturity": "It has been extensively benchmarked and used to interpret spectra, magnetism, and metal-insulator phenomena.",
        "uncertainties": [
          "Its development was cumulative and involved a substantial wider community."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B037",
      "proposed_laureates": [
        "John J. Croat",
        "Masato Sagawa"
      ],
      "assessment": {
        "nobel_worthiness": "Neodymium-iron-boron magnets are an exceptional materials discovery with enduring physical and technological consequences.",
        "attribution": "Croat and Sagawa are the clear central independent inventors of the high-performance Nd-Fe-B magnet family.",
        "maturity": "The materials science, exceptional magnetic performance, and immense practical importance have been confirmed over decades.",
        "uncertainties": [
          "The relative framing of parallel invention and subsequent optimization needs precise historical review."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps created a durable conceptual and experimental platform for controlling light in structured media.",
        "attribution": "John and Yablonovitch articulated foundational photonic-crystal ideas, while Joannopoulos made decisive theoretical and computational contributions.",
        "maturity": "The central physics is firmly established and has generated a broad experimental and device literature.",
        "uncertainties": [
          "The discovery spans several early theoretical and experimental lines, making the exact laureate boundary difficult."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle graphene revealed an unexpectedly rich and tunable correlated-electron platform in a simple van der Waals structure.",
        "attribution": "Bistritzer and MacDonald supplied the essential magic-angle theory, and Jarillo-Herrero established the striking experimental phenomena.",
        "maturity": "The flat-band mechanism and central correlated phases have been widely reproduced and explored.",
        "uncertainties": [
          "The ultimate universality and microscopic interpretation of all observed phases remain unsettled."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and phase effects exposed a deep feature of quantum mechanics that has influenced condensed matter, optics, and quantum technology.",
        "attribution": "Aharonov is central to the experimentally consequential phase effect, and Berry formulated the broadly applicable adiabatic geometric phase.",
        "maturity": "Both effects are long established experimentally and theoretically.",
        "uncertainties": [
          "They are distinct discoveries, so the unity of a single prize citation needs careful justification."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Henry J. Snaith",
        "Nam-Gyu Park",
        "Tsutomu Miyasaka"
      ],
      "assessment": {
        "nobel_worthiness": "Metal-halide perovskite solar cells opened an unusually powerful new semiconductor-photovoltaic platform with major potential societal impact.",
        "attribution": "Miyasaka and Park pioneered the early device concept and performance breakthrough, with Snaith central to its development into a major photovoltaic field.",
        "maturity": "Efficiency advances and the underlying optoelectronic physics are compelling and extensively replicated.",
        "uncertainties": [
          "Long-term stability, scalable manufacture, and environmental handling remain important unresolved practical tests."
        ]
      }
    }
  ]
